function OverseaManageCustomerTalkingNode:InitNodeEnv()
    if not isNull(self.ItemSubmission) then
        local env = CfUtils.GetLuaScr(self.ItemSubmission,"Game.MaidCoffee.MaidCoffeeGuestUIDialog.OverseaManageTalkingSubGoodsNode")
        if not isNull(env) then
            env:SetSubCallBack(Bind(self,self.OnSubCallBack))
            self.subGoodsEnv = env
        end
    end

    self.optionEnv = {}
    for i = 1, OptionCount do
        local optionNode = self["BtnOption"..i]
        if optionNode then
            local env = CfUtils.GetLuaScr(optionNode,OptionPath)
            if not isNull(env) then
                env:SetOptionCallBack(Bind(self,self.OnOptionCellClick))
                self.optionEnv[i] = env
            end
        end
    end
end

