    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)

            local startIndex = 1
            if self.controller.Argument.extra then
                local str = string.split(self.controller.Argument.extra,"_")
                startIndex = checkNumber(str[1])
                if checkNumber(str[2]) > 0 then
                    self.choicesIndex = str[2]
                end
            end
            self:StartTalking(startIndex)
        end)
    end))
    return coWait
end

function OverseaManageCustomerTalkingNode:StartTalking(index)
    self:InitUI()
