function OverseaManageCustomerTalkingNode:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:StopCo()
            if self.onExit then
                self.onExit = false
                Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeFinishEvents,{eventData = self.parameters.data,choice = self.choicesData,subData = self.subData,choiceId = self.choicesId})
            end
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            if not isNull(self.subGoodsEvent) then
                Events.RemoveListener(Constants.EventNames.MaidCoffeeGuestSubGoods,self.subGoodsEvent)
                self.subGoodsEvent = nil
            end

            --- 显示 WorldSpaceCanvas:
            Events.Broadcast(MaidCoffeeConstants.EventNames.ShowWorldSpaceCanvas, true )

            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

